package org.springframework.samples.petclinic.service;

import java.util.Collection;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Populates the derived registration fields on a newly created owner: its identifier,
 * counters and warnings computed against the existing owners. This keeps the enrichment as
 * one cohesive unit, separate from the request-handling concerns of the controller.
 */
public final class OwnerRegistration {

    private OwnerRegistration() {
    }

    public static void enrich(Collection<Owner> owners, Owner owner, Boolean sharesHousehold) {
        owner.setNamesakeCount(NamesakeCounter.count(owners, owner));
        owner.setCustomerCode(CustomerCodeGenerator.generate(owners, owner));
        owner.setBulkSignupWarning(BulkSignupWarning.isTriggered(owners));
        owner.setCapacityWarning(CityCapacity.isApproaching(owners, owner));
        owner.setHouseholdSize(HouseholdMatcher.householdSize(owners, owner));
        owner.setPossibleDuplicateOf(HouseholdMatcher.possibleDuplicateOf(owners, owner, sharesHousehold));
        owner.setMembershipLevel(HouseholdLevelCap.cap(owners, owner));
    }
}

